import { expect, Journey, test } from './journey.js';

// Verifies: CMS-004
test("Following a link opens the article without a page load", async ({ browser, baseURL, page, context }) => {
  const j = await Journey.start({ browser, baseURL, page, context }, [], { logs: false });
  try {
    await j.goto("/");
    await j.mark("loaded");
    await j.page.getByRole("link", { name: "What the Kiln Decides", exact: true }).click();
    await j.expectScreen("screen-article", undefined);
    await j.expectAddress("/posts/what-the-kiln-decides", {}, [], undefined);
    await expect(j.page.getByRole("heading", { name: "What the Kiln Decides", exact: true, level: 1 })).toBeVisible();
    await expect(j.page).toHaveTitle("What the Kiln Decides — Fieldnotes");
    await expect(j.page.getByRole("main", { name: "Content", exact: true })).toBeFocused();
    await expect(j.page.getByRole("complementary", { name: "About this essay", exact: true }).getByRole("link", { name: "Mirela Ashby", exact: true })).toBeVisible();
    await j.expectText(j.page.getByRole("blockquote"), j.text("You do not finish a pot"), undefined);
    await j.expectNoReload("loaded");
    await j.back();
    await expect(j.page.getByRole("heading", { name: "The Jig Is the Work", exact: true, level: 2 })).toBeVisible();
    await j.expectNoReload("loaded");
  } finally {
    await j.close();
  }
});
